const PlaywrightWrapper = require("../Framework/src/helper/wrapper/PlaywrightWrappers");

class CartPage {
    constructor(page, logger) {
        this.page = page;
        this.logger = logger;
        this.base = new PlaywrightWrapper(page, logger);
        this.Elements = {
            cartItem: ".cart_item",
            itemName: ".inventory_item_name",
            itemDescription: ".inventory_item_desc",
            itemPrice: ".inventory_item_price",
            itemQuantity: ".cart_quantity",
            removeButton: ".cart_button",
            checkoutButton: "[data-test='checkout']",
            continueShoppingButton: "[data-test='continue-shopping']",
            cartBadge: ".shopping_cart_badge"
        };
    }

    async getCartItemCount() {
        return this.base.count(this.Elements.cartItem);
    }

    async getCartItemNames() {
        return this.base.allTextContents(this.Elements.itemName);
    }

    getCartItemByName(productName) {
        return this.page.locator(this.Elements.cartItem).filter({ hasText: productName });
    }

    async removeItemByName(productName) {
        const item = this.getCartItemByName(productName);
        await this.base.withHeal(
            null,
            async () => {
                const btn = item.locator(this.Elements.removeButton);
                await btn.waitFor({ state: "visible" });
                await btn.click();
            },
            `Remove Cart Item (${productName})`,
            "click",
            this.Elements.removeButton
        );
    }

    async isCartBadgeVisible() {
        return this.base.isVisible(this.Elements.cartBadge);
    }

    async clickCheckout() {
        await this.base.waitAndClick(this.Elements.checkoutButton, "Checkout Button");
    }

    async clickContinueShopping() {
        await this.base.waitAndClick(this.Elements.continueShoppingButton, "Continue Shopping Button");
    }
}

module.exports = CartPage;
